"""Suite 3: edit student/subject pages, password reset, semester + one-form-per-semester rules, cancel, courses."""
from helpers import *
LOGIN = login

def student_post(**kw):
    d={"username":"tester3","password":"pw3333","snum":"2026-003","course":"bsit","yrlvlsec":"I-1","fname":"Tee","minitial":"T","lname":"Three","gender":"female","bdate":"2005-01-02","address":"Roxas","cnumber":"09123456789","email":"t3@e.com","fathername":"F","mothername":"M","guardianname":"G","bplace":"Roxas","cstatus":"single","elemschool":"E","yrgradelem":"2016","hschool":"H","yrgradhs":"2020","lastschool":"L","yrlast":"2022","address2":"x","register":"x"}
    d.update(kw); return d

a=client(); LOGIN(a,"admins","admins"); d=client(); LOGIN(d,"dennis","123456")
section("access control on new pages")
anon=client(); st=client(); LOGIN(st,"dennis","123456")
for p in ["Admin/edituser.php?id=2","Admin/editsubject.php?id=1","Admin/courses.php"]:
    check("logged-out redirected: "+p, anon(p)[0]==302); check("student redirected: "+p, st(p)[0]==302)

section("add student (needs token) + edit form")
s,h,_=a("Admin/addnewuser.php"); tk=token(h)
check("add form renders, course list from database, no warnings", s==200 and "value=\"bsit\"" in h and "value=\"bscs\"" in h and not warns(h), warns(h))
s,h,_=a("Admin/addnewuser.php",student_post()); check("add without token rejected", "expired" in al(h) and sql("select count(*) from usertbl where username='tester3'")=="0", al(h))
s,h,_=a("Admin/addnewuser.php",student_post(token=tk,course="nope")); check("invalid course rejected", "valid course" in al(h))
s,h,_=a("Admin/addnewuser.php",student_post(token=tk))
assigned_id = re.search(r"Student ID: (RU-[0-9]+)", al(h)).group(1)
check("registrar receives assigned ID", sql(f"select count(*) from usertbl where username='{assigned_id}'")=="1")
# These edit tests cover pre-migration records with independently editable account and student IDs.
sql(f"update usertbl set username='tester3', must_change_password=0 where username='{assigned_id}'")
sql(f"update studenttbl set studnum='2026-003' where studnum='{assigned_id}'")
sid=sql("select ID from studenttbl where studnum='2026-003'")
s,h,_=a("Admin/userreg.php"); check("user list has EDIT link for the new student, no warnings", f"edituser.php?id={sid}" in h and not warns(h), warns(h))

section("edit student")
s,h,_=a("Admin/edituser.php?id="+sid); tk=token(h)
check("edit form is pre-filled (name, email, course, year-graduated, birthdate)", all(x in h for x in ['value="Tee"','value="t3@e.com"','value="2005-01-02"']) and re.search(r"<option value='2016' selected",h) and re.search(r'value="bsit" selected',h) and not warns(h), warns(h))
check("password box empty, labelled Reset Password", 'Reset Password' in h and 'type=\'password\'' in h)
s,h,_=a("Admin/edituser.php?id=99999"); check("unknown student -> friendly message + redirect", "not found" in al(h))
s,h,_=a("Admin/edituser.php",student_post(id=sid,save="x",fname="Hack",username="tester3",password="")); check("save without token rejected", "expired" in al(h) and sql("select fname from studenttbl where ID=%s"%sid)=="Tee")
old=sql("select password from usertbl where username='tester3'")
s,h,_=a("Admin/edituser.php",student_post(id=sid,save="x",token=tk,fname="Teeny",lname="Threeish",email="new@e.com",yrlvlsec="II-1",course="bscs",password="",snum="2026-003"))
check("save updates profile fields", sql("select fname,lname,emailaddress,yearlvl,course from studenttbl where ID=%s"%sid)=="Teeny\tThreeish\tnew@e.com\tII-1\tbscs" and "updated" in al(h), (al(h), sql("select fname from studenttbl where ID=%s"%sid)))
check("fullname in usertbl follows the name", sql("select fullname from usertbl where username='tester3'")=="Teeny T Threeish")
check("blank password keeps old password", sql("select password from usertbl where username='tester3'")==old)
s,h,_=a("Admin/edituser.php",student_post(id=sid,save="x",token=tk,fname="Teeny",password="reset999",snum="2026-003",username="tester3"))
check("reset password: stored hashed and different", sql("select password from usertbl where username='tester3'").startswith("$2y$") and sql("select password from usertbl where username='tester3'")!=old)
t3=client(); s,h,_=LOGIN(t3,"tester3","reset999"); check("student can log in with the reset password", "Student" in h)
s,h,_=LOGIN(client(),"tester3","pw3333"); check("old password no longer works", "doesn't exist" in al(h))
s,h,_=a("Admin/edituser.php",student_post(id=sid,save="x",token=tk,username="dennis",snum="2026-003")); check("duplicate username -> friendly message", "already taken" in al(h), al(h))
s,h,_=a("Admin/edituser.php",student_post(id=sid,save="x",token=tk,snum="2014-052",username="tester3")); check("duplicate student number -> friendly message", "already registered" in al(h), al(h))
check("a failed save changes nothing (transaction)", sql("select username from usertbl where ID=(select accountID from studenttbl where ID=%s)"%sid)=="tester3" and sql("select studnum from studenttbl where ID=%s"%sid)=="2026-003")
s,h,_=a("Admin/edituser.php",student_post(id=sid,save="x",token=tk,fname="<script>alert(1)</script>",snum="2026-003",username="tester3"))
s,h,_=a("Admin/edituser.php?id="+sid); check("edit form escapes stored HTML", "<script>alert(1)</script>" not in h and "&lt;script&gt;" in h)
s,h,_=a("Admin/edituser.php?id=1"); check("admin accounts cannot be opened through edituser", "not found" in al(h) or sql("select user_type from usertbl where ID=1")!="student")

section("subjects: add / edit / guards")
s,h,_=a("Admin/addnewsubj.php"); tk=token(h)
sp={"course":"bsit","stitle":"Edit Me","scode":"ED1","cdescription":"d","numunits":"3","sroom":"","stime":"","sday":"","sinstructor":"","register":"x","token":tk}
s,h,_=a("Admin/addnewsubj.php",sp); check("add subject (room/day/time/instructor may be blank now)", "Successfully Created" in al(h), al(h))
subid=sql("select ID from subjecttbl where subjectcode='ED1'")
s,h,_=a("Admin/subjectreg.php"); check("subject list has EDIT link", f"editsubject.php?id={subid}" in h and not warns(h))
s,h,_=a("Admin/editsubject.php?id="+subid); tk=token(h); check("edit subject form pre-filled", 'value="Edit Me"' in h and 'value="ED1"' in h and not warns(h), warns(h))
ep=dict(sp); ep.pop("register"); ep.update(save="x",id=subid,token=tk,stitle="Edited Title",numunits="4",islab="on",sroom="R5",course="bsit")
s,h,_=a("Admin/editsubject.php",{**ep,"token":"bad"}); check("edit subject without valid token rejected", "expired" in al(h))
s,h,_=a("Admin/editsubject.php",ep); check("edit subject saves (title, units, lab flag, room)", sql("select subjecttitle,numofunits,islab,room from subjecttbl where ID=%s"%subid)=="Edited Title\t4\t1\tR5" and "updated" in al(h), al(h))
s,h,_=a("Admin/editsubject.php",{**ep,"numunits":"9"}); check("invalid units rejected", "1 to 6" in al(h))
s,h,_=a("Admin/editsubject.php",{**ep,"scode":"IT201"}); check("duplicate code rejected", "already exists" in al(h), al(h))
s,h,_=a("Admin/editsubject.php",{**ep,"scode":"ED1-RENAMED"}); check("unused subject code can be renamed", sql("select subjectcode from subjecttbl where ID=%s"%subid)=="ED1-RENAMED", al(h))
sql("update subjecttbl set subjectcode='ED1' where ID=%s"%subid)

section("enrollment: semester stored, one form per semester")
sql("delete from student_subject")
s,h,_=d("student/enroll.php"); tk=token(h)
s,h,_=d("student/showsubs.php",{"subject[]":["IT201","IT202"],"sem":"1st Sem","reg":"x","token":tk})
check("form saved with semester and school year", sql("select subjects,totalunits,semester,school_year,approved from student_subject")=="IT201,IT202\t4\t1st Sem\t2026 - 2027\t0", sql("select * from student_subject"))
s,h,_=d("student/showsubs.php",{"subject[]":["IT201"],"sem":"1st Sem","register":"x","token":tk}); check("second form for the same semester is refused at the preview step", "waiting for approval" in al(h) and "Cancel it" in al(h), al(h))
s,h,_=d("student/showsubs.php",{"subject[]":["IT201"],"sem":"1st Sem","reg":"x","token":tk}); check("...and also when posted straight to submit", sql("select count(*) from student_subject")=="1")
s,h,_=d("student/showsubs.php",{"subject[]":["IT201"],"sem":"2nd Sem","reg":"x","token":tk}); check("a different semester is allowed", sql("select count(*) from student_subject")=="2" and "successfully" in al(h), al(h))
s,h,_=d("student/report.php"); check("student report shows both semesters + Cancel buttons, no warnings", "1st Sem 2026 - 2027" in h and "2nd Sem 2026 - 2027" in h and h.count("cancel_form")==2 and not warns(h), warns(h))
id1=sql("select ID from student_subject where semester='1st Sem'"); id2=sql("select ID from student_subject where semester='2nd Sem'")
section("cancel rules")
s,h,_=a("Admin/approvals.php"); tk=token(h); check("approvals shows semester column", "1st Sem 2026 - 2027" in h and not warns(h), warns(h))
a("Admin/approvals.php",{"form_id":id1,"action":"approve","token":tk})
s,h,_=d("student/report.php"); ctk=token(h)
s,h,_=d("student/report.php",{"cancel_form":id1,"token":ctk}); check("approved form cannot be cancelled by the student", sql("select count(*) from student_subject where ID=%s"%id1)=="1" and "cannot be cancelled" in al(h), al(h))
s,h,_=d("student/report.php",{"cancel_form":id2}); check("cancel without token rejected", sql("select count(*) from student_subject where ID=%s"%id2)=="1")
# another student's form
sql("insert into student_subject (studentID,subjects,totalunits,approved,semester,school_year) values ('2026-003','IT201',2,0,'1st Sem','2026 - 2027')")
oid=sql("select ID from student_subject where studentID='2026-003'")
s,h,_=d("student/report.php",{"cancel_form":oid,"token":ctk}); check("a student cannot cancel someone else's form", sql("select count(*) from student_subject where ID=%s"%oid)=="1")
s,h,_=d("student/report.php",{"cancel_form":id2,"token":ctk}); check("pending form can be cancelled", sql("select count(*) from student_subject where ID=%s"%id2)=="0" and "cancelled" in al(h), al(h))
s,h,_=d("student/showsubs.php",{"subject[]":["IT202"],"sem":"2nd Sem","reg":"x","token":tk if False else token(d("student/enroll.php")[1])}); check("after cancelling, a new form for that semester can be submitted", sql("select count(*) from student_subject where studentID='2014-052' and semester='2nd Sem'")=="1", al(h))
s,h,_=a("Admin/approvals.php",{"form_id":id1,"action":"pending","token":token(a("Admin/approvals.php")[1])}); 
s,h,_=d("student/report.php"); check("admin can set approved form back to pending, then student may cancel it", "cancel_form" in h and h.count('name="cancel_form"')==2)
s,h,_=a("Admin/report.php"); check("admin report shows semester, no warnings", "1st Sem 2026 - 2027" in h and "Semester" in h and not warns(h), warns(h))

section("delete subject used in a form")
s,h,_=a("Admin/subjectreg.php"); tk=token(h); it201=sql("select ID from subjecttbl where subjectcode='IT201'")
s,h,_=a("Admin/deletecurrsubj.php",{"accid":it201,"token":tk}); check("subject used in a form cannot be deleted (friendly message)", "used in" in al(h) and sql("select count(*) from subjecttbl where subjectcode='IT201'")=="1", al(h))
s,h,_=a("Admin/editsubject.php?id="+it201); etk=token(h)
s,h,_=a("Admin/editsubject.php",{"id":it201,"save":"x","token":etk,"course":"bsit","scode":"IT201X","stitle":"File Organization","numunits":"2"}); check("subject used in a form cannot be renamed", "cannot be changed" in al(h) and sql("select count(*) from subjecttbl where subjectcode='IT201'")=="1", al(h))
s,h,_=a("Admin/deletecurrsubj.php",{"accid":subid,"token":tk}); check("unused subject can be deleted", "Successfully Removed" in al(h) and sql("select count(*) from subjecttbl where ID=%s"%subid)=="0", al(h))

section("courses")
s,h,_=a("Admin/courses.php"); tk=token(h); check("courses page lists BSIT/BSCS with counts, no warnings", s==200 and "BSIT" in h and "BSCS" in h and not warns(h), warns(h))
cp={"action":"add","course_code":"BSBA","course_title":"Bachelor of Science in Business","course_desc":"d","token":tk}
s,h,_=a("Admin/courses.php",{**cp,"token":""}); check("add without token rejected", sql("select count(*) from courses_tbl where course_code='bsba'")=="0")
s,h,_=a("Admin/courses.php",cp); check("add course (code lower-cased)", sql("select course_code from courses_tbl where course_code='bsba'")=="bsba" and "added" in al(h), al(h))
s,h,_=a("Admin/courses.php",cp); check("duplicate code -> friendly message", "already exists" in al(h), al(h))
s,h,_=a("Admin/courses.php",{**cp,"course_code":"bad code!"}); check("bad characters in code rejected", "can only use" in al(h))
s,h,_=a("Admin/courses.php",{**cp,"course_title":""}); check("empty title rejected", "required" in al(h))
cid=sql("select course_ID from courses_tbl where course_code='bsba'")
s,h,_=a("Admin/courses.php?edit="+cid); check("edit form pre-filled", 'value="bsba"' in h and "Edit Course" in h)
s,h,_=a("Admin/courses.php",{"action":"save","course_id":cid,"course_code":"bsba2","course_title":"Business","course_desc":"","token":tk}); check("edit course saves", sql("select course_code,course_title from courses_tbl where ID=%s"%cid if False else "select course_code,course_title from courses_tbl where course_ID=%s"%cid)=="bsba2\tBusiness", al(h))
s,h,_=a("Admin/addnewsubj.php"); check("new course appears in the Add Subject course list", 'value=\'bsba2\'' in h or 'value="bsba2"' in h)
s,h,_=a("Admin/courses.php",{"action":"delete","course_id":"1","token":tk}); check("course with students/subjects cannot be deleted (explains why)", "cannot be deleted" in al(h) and "student(s)" in al(h) and sql("select count(*) from courses_tbl where course_ID=1")=="1", al(h))
s,h,_=a("Admin/courses.php",{"action":"delete","course_id":cid,"token":tk}); check("empty course can be deleted", sql("select count(*) from courses_tbl where course_ID=%s"%cid)=="0" and "deleted" in al(h), al(h))
s,h,_=a("Admin/courses.php",{"action":"delete","course_id":"9999","token":tk}); check("deleting a missing course -> message", "no longer exists" in al(h))
s,h,_=a("Admin/courses.php",{"action":"delete","course_id":"1"}); check("delete without token rejected", sql("select count(*) from courses_tbl where course_ID=1")=="1")

section("menus / delete student with forms")
s,h,_=a("Admin/adminindex.php"); check("menu has Courses and Approvals", "courses.php" in h and "approvals.php" in h)
s,h,_=a("Admin/userreg.php"); tk=token(h)
s,h,_=a("Admin/deletecurruser.php",{"accid":sid,"token":tk}); check("deleting a student removes profile, account and forms (cascade)", sql("select count(*) from usertbl where username='tester3'")=="0" and sql("select count(*) from student_subject where studentID='2026-003'")=="0", al(h))
finish()
